-- Back cover Template (bìa sau 15 × 11,7 cm): thêm loại mẫu 'back' + danh mục "Cơ bản" + 5 mẫu có sẵn.
alter table public.design_templates drop constraint if exists design_templates_kind_check;
alter table public.design_templates add constraint design_templates_kind_check check (kind in ('custom_cd', 'cd', 'booklet_single', 'booklet_spread', 'back'));
alter table public.template_categories drop constraint if exists template_categories_scope_check;
alter table public.template_categories add constraint template_categories_scope_check check (scope in ('cd', 'booklet_single', 'booklet_spread', 'booklet_bundle', 'back'));

insert into public.template_categories (scope, name, sort_order) values ('back', 'Cơ bản', 0)
on conflict (scope, name) do nothing;

insert into public.design_templates (kind, name, category_id, config, photo_count, is_active, sort_order)
select 'back', v.name, (select id from public.template_categories where scope = 'back' and name = 'Cơ bản'), v.config::jsonb, v.n, true, v.s
from (values
  ('Polaroid ba ảnh', $j${"template": {"id": "back-1", "n": 3, "style": "polaroid", "seed": 1, "surface": "back", "bg": {"color": "#fff4ec", "pattern": "dots", "ink": "#f4c7b8"}, "layers": [{"k": "photo", "slot": 0, "x": 40, "y": 50, "w": 38, "h": 46, "rot": -6, "shape": "polaroid", "seed": 11}, {"k": "photo", "slot": 1, "x": 75, "y": 46, "w": 38, "h": 46, "rot": 3, "shape": "polaroid", "seed": 12}, {"k": "photo", "slot": 2, "x": 110, "y": 52, "w": 38, "h": 46, "rot": -2, "shape": "polaroid", "seed": 13}, {"k": "text", "role": "custom", "value": "our little moments", "x": 75, "y": 97, "w": 110, "size": 8, "rot": 0, "font": "hand", "color": "#c2410c", "align": "center"}, {"k": "sticker", "x": 22, "y": 20, "s": 8, "rot": -10, "shape": "heart", "color": "#ff5fa2"}, {"k": "sticker", "x": 128, "y": 94, "s": 7, "rot": 12, "shape": "star", "color": "#f59e0b"}]}}$j$, 3, 1),
  ('Tracklist bên phải', $j${"template": {"id": "back-2", "n": 1, "style": "magazine", "seed": 2, "surface": "back", "bg": {"color": "#f4f1ea", "pattern": "lines", "ink": "#d6d3d1"}, "layers": [{"k": "photo", "slot": 0, "x": 46, "y": 58, "w": 62, "h": 86, "rot": 0, "shape": "rect", "seed": 21}, {"k": "tape", "x": 46, "y": 16, "w": 22, "h": 7, "rot": -4, "color": "#fde68a", "pattern": "stripe", "seed": 22}, {"k": "text", "role": "custom", "value": "TRACKLIST", "x": 108, "y": 22, "w": 56, "size": 6, "rot": 0, "font": "label", "color": "#18181b", "align": "center"}, {"k": "text", "role": "custom", "value": "01. Bài hát số 1\n02. Bài hát số 2\n03. Bài hát số 3\n04. Bài hát số 4\n05. Bài hát số 5", "x": 108, "y": 60, "w": 56, "size": 4.2, "rot": 0, "font": "marker", "color": "#3f3f46", "align": "left", "lh": 1.5}, {"k": "sticker", "x": 130, "y": 104, "s": 6, "rot": 0, "shape": "sparkle", "color": "#f59e0b"}]}}$j$, 1, 2),
  ('Lưới bốn ảnh', $j${"template": {"id": "back-3", "n": 4, "style": "ring", "seed": 3, "surface": "back", "bg": {"color": "#fff0f6", "pattern": "grid", "ink": "#fbcfe8"}, "layers": [{"k": "photo", "slot": 0, "x": 36, "y": 33, "w": 34, "h": 40, "rot": 0, "shape": "rect", "seed": 31}, {"k": "photo", "slot": 1, "x": 74, "y": 33, "w": 34, "h": 40, "rot": 0, "shape": "rect", "seed": 32}, {"k": "photo", "slot": 2, "x": 36, "y": 82, "w": 34, "h": 40, "rot": 0, "shape": "rect", "seed": 33}, {"k": "photo", "slot": 3, "x": 74, "y": 82, "w": 34, "h": 40, "rot": 0, "shape": "rect", "seed": 34}, {"k": "text", "role": "custom", "value": "Best\nFriends\nForever", "x": 117, "y": 58, "w": 40, "size": 7, "rot": 0, "font": "hand", "color": "#be185d", "align": "center", "lh": 1.2}, {"k": "sticker", "x": 127, "y": 20, "s": 9, "rot": 8, "shape": "flower", "color": "#f472b6"}, {"k": "sticker", "x": 128, "y": 98, "s": 7, "rot": 0, "shape": "sparkle", "color": "#f59e0b"}]}}$j$, 4, 3),
  ('Ảnh tròn', $j${"template": {"id": "back-4", "n": 3, "style": "floral", "seed": 4, "surface": "back", "bg": {"color": "#eef6ff", "pattern": "dots", "ink": "#bfdbfe"}, "layers": [{"k": "photo", "slot": 0, "x": 46, "y": 52, "w": 52, "h": 52, "rot": 0, "shape": "circle", "seed": 41}, {"k": "photo", "slot": 1, "x": 98, "y": 40, "w": 36, "h": 36, "rot": 0, "shape": "circle", "seed": 42}, {"k": "photo", "slot": 2, "x": 110, "y": 80, "w": 28, "h": 28, "rot": 0, "shape": "circle", "seed": 43}, {"k": "text", "role": "custom", "value": "Happy Graduation", "x": 75, "y": 103, "w": 120, "size": 8, "rot": 0, "font": "hand", "color": "#1d4ed8", "align": "center"}, {"k": "sticker", "x": 126, "y": 16, "s": 8, "rot": 0, "shape": "star", "color": "#fbbf24"}, {"k": "sticker", "x": 22, "y": 96, "s": 6, "rot": -12, "shape": "star", "color": "#93c5fd"}]}}$j$, 3, 4),
  ('Giấy xé dán', $j${"template": {"id": "back-5", "n": 2, "style": "torn", "seed": 5, "surface": "back", "bg": {"color": "#fbf3e7", "pattern": "plain", "ink": "#e7d8c3"}, "layers": [{"k": "paper", "x": 75, "y": 58, "w": 120, "h": 96, "rot": -1, "paper": "kraft", "color": "#e9d5b5", "torn": true, "seed": 51}, {"k": "photo", "slot": 0, "x": 54, "y": 56, "w": 56, "h": 70, "rot": -4, "shape": "torn", "seed": 52}, {"k": "photo", "slot": 1, "x": 108, "y": 44, "w": 34, "h": 42, "rot": 5, "shape": "polaroid", "seed": 53}, {"k": "tape", "x": 54, "y": 22, "w": 20, "h": 7, "rot": 6, "color": "#fca5a5", "pattern": "dots", "seed": 54}, {"k": "text", "role": "custom", "value": "Thanh xuân\ncủa chúng mình", "x": 108, "y": 88, "w": 44, "size": 5.5, "rot": 0, "font": "marker", "color": "#78350f", "align": "center", "lh": 1.3}, {"k": "sticker", "x": 128, "y": 104, "s": 6, "rot": 0, "shape": "heart", "color": "#ef4444"}]}}$j$, 2, 5)
) as v(name, config, n, s)
where not exists (select 1 from public.design_templates d where d.kind = 'back' and d.name = v.name);
